// ARM_Local_Translation_Interface_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module ARM_Local_Translation_Interface_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [7:0] c_cfg_sid,
  input logic [7:0] c_cfg_ssid,
  input logic  c_cfg_ssidv,
  input logic [2:0] c_cfg_idx,
  input logic  c_cfg_v,
  input logic [3:0] c_cfg_perm,
  input logic [19:0] c_cfg_va,
  input logic [7:0] c_cfg_attr,
  input logic [19:0] c_cfg_pa,
  input logic  c_inv_all,
  input logic [7:0] c_inv_sid,
  input logic [3:0] c_ctags_out,
  input logic  c_cfg_we,
  input logic  c_inv_valid,
  input logic  c_inv_ready,
  input logic  c_ev_fault,
  input logic  c_ev_proto,
  input logic  c_inv_done
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 10;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:9];          // model of every stored word
  logic [4:0] m_set;                // interrupt bits set this clock
  logic m_state_TBL;          // full / valid pulse / available
  logic m_state_INV;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_ev_fault) m_set[0] = 1'b1;
    if (c_ev_proto) m_set[1] = 1'b1;
    if (c_inv_done) m_set[2] = 1'b1;
    if (m_state_INV && c_inv_ready) m_set[3] = 1'b1;
    if (m_wr && m_map && (m_idx == 8) && m_state_INV) m_set[4] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_state_TBL <= 0;
      m_state_INV <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFF;
      m_state_TBL <= m_wr && m_map && m_idx == 7;
      if (m_wr && m_map && m_idx == 8 && !m_state_INV) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'h1FF;
      if (m_wr && m_map && m_idx == 8 && !m_state_INV) m_state_INV <= 1;
      if (m_state_INV && c_inv_ready) m_state_INV <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h4C540200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_INV});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return (32'(c_ctags_out) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][4:0] & m_w[2][4:0]))
  `SVA_INV(a_core_cfg_sid, c_cfg_sid == m_w[5][7:0])
  `SVA_INV(a_core_cfg_ssid, c_cfg_ssid == m_w[5][15:8])
  `SVA_INV(a_core_cfg_ssidv, c_cfg_ssidv == m_w[5][16:16])
  `SVA_INV(a_core_cfg_idx, c_cfg_idx == m_w[5][19:17])
  `SVA_INV(a_core_cfg_v, c_cfg_v == m_w[5][20:20])
  `SVA_INV(a_core_cfg_perm, c_cfg_perm == m_w[5][24:21])
  `SVA_INV(a_core_cfg_va, c_cfg_va == m_w[6][19:0])
  `SVA_INV(a_core_cfg_attr, c_cfg_attr == m_w[6][27:20])
  `SVA_INV(a_core_cfg_pa, c_cfg_pa == m_w[7][19:0])
  `SVA_INV(a_core_inv_all, c_inv_all == m_w[8][0:0])
  `SVA_INV(a_core_inv_sid, c_inv_sid == m_w[8][8:1])
  `SVA_INV(a_core_cfg_we, c_cfg_we == m_state_TBL)
  `SVA_INV(a_core_inv_valid, c_inv_valid == m_state_INV)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_sid == 8'h0 && c_cfg_ssid == 8'h0 && c_cfg_ssidv == 1'h0 && c_cfg_idx == 3'h0 && c_cfg_v == 1'h0 && c_cfg_perm == 4'h0 && c_cfg_va == 20'h0 && c_cfg_attr == 8'h0 && c_cfg_pa == 20'h0 && c_inv_all == 1'h0 && c_inv_sid == 8'h0 && !c_cfg_we && !c_inv_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_TBL0, m_rd && m_map && m_idx == 5)
  `FC(wr_TBL0, m_wr && m_map && m_idx == 5)
  `FC(rd_TBL1, m_rd && m_map && m_idx == 6)
  `FC(wr_TBL1, m_wr && m_map && m_idx == 6)
  `FC(rd_TBL2, m_rd && m_map && m_idx == 7)
  `FC(wr_TBL2, m_wr && m_map && m_idx == 7)
  `FC(rd_INV, m_rd && m_map && m_idx == 8)
  `FC(wr_INV, m_wr && m_map && m_idx == 8)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 9)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 9)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_FAULT_set, m_set[0])
  `FC(irq_FAULT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_FAULT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_FAULT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_PROTO_set, m_set[1])
  `FC(irq_PROTO_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_PROTO_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_PROTO_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_SYNC_set, m_set[2])
  `FC(irq_SYNC_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_SYNC_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_SYNC_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_INV_DONE_set, m_set[3])
  `FC(irq_INV_DONE_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_INV_DONE_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_INV_DONE_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_INV_OVF_set, m_set[4])
  `FC(irq_INV_OVF_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_INV_OVF_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_INV_OVF_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(TBL_commit, m_state_TBL)
  `FC(INV_handshake, m_state_INV && c_inv_ready)
  `FC(INV_backpressure, m_state_INV && !c_inv_ready)
  `FC(INV_write_while_full, m_wr && m_map && m_idx == 8 && m_state_INV)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind ARM_Local_Translation_Interface_apb ARM_Local_Translation_Interface_apb_sva u_apb_sva (.*);
